<?php require_once __DIR__.'/includes/auth.php'; $pageTitle='Explore events'; $q=trim($_GET['q']??'');$cat=trim($_GET['category']??'');$sort=($_GET['sort']??'date')==='title'?'e.title':'e.event_date';$sql="SELECT e.*,(SELECT COUNT(*) FROM registrations r WHERE r.event_id=e.id AND r.status='valid') registered_count FROM events e WHERE e.status IN ('published','closed','cancelled')";$params=[];if($q!==''){$sql.=' AND (e.title LIKE ? OR e.description LIKE ? OR e.venue LIKE ?)';$params=["%$q%","%$q%","%$q%"]; }if($cat!==''){$sql.=' AND e.category=?';$params[]=$cat;}$sql.=" ORDER BY $sort ASC";$st=$pdo->prepare($sql);$st->execute($params);$events=$st->fetchAll();$cats=$pdo->query('SELECT DISTINCT category FROM events ORDER BY category')->fetchAll(PDO::FETCH_COLUMN);require __DIR__.'/includes/header.php'; ?>
<section class="section section-soft"><div class="container"><span class="eyebrow">Explore campus life</span><h1 class="mt-3">Discover events</h1><p class="muted">Find your people, learn something new, and make the most of campus.</p><form class="panel row g-3 align-items-end mt-4" method="get" data-validate novalidate data-no-lock><div class="col-md-5"><label class="form-label">Search events</label><input class="form-control" name="q" maxlength="80" value="<?=e($q)?>" placeholder="Try hackathon, music, workshop…"></div><div class="col-md-3"><label class="form-label">Category</label><select class="form-select" name="category"><option value="">All categories</option><?php foreach($cats as $c): ?><option <?=($cat===$c?'selected':'')?> value="<?=e($c)?>"><?=e($c)?></option><?php endforeach; ?></select></div><div class="col-md-2"><label class="form-label">Sort by</label><select class="form-select" name="sort"><option value="date" <?=($sort==='e.event_date'?'selected':'')?>>Date</option><option value="title" <?=($sort==='e.title'?'selected':'')?>>Name</option></select></div><div class="col-md-2 d-grid"><button class="btn btn-primary">Apply filters</button></div></form><div class="row g-4 mt-2"><?php if(!$events): ?><div class="col-12"><div class="empty-state panel"><i class="bi bi-search fs-1"></i><h2 class="h5 mt-3">No events match your search</h2><p>Try another keyword or clear your filters.</p><a href="events.php" class="btn btn-outline-primary">Clear filters</a></div></div><?php endif; ?><?php foreach($events as $ev): $remaining=max(0,(int)$ev['capacity']-(int)$ev['registered_count']); ?><div class="col-md-6 col-lg-4"><article class="event-card"><img class="event-img" src="<?=e(event_image($ev['image_url']))?>" alt="<?=e($ev['title'])?>" onerror="this.src='https://placehold.co/800x500/eef2ff/315eea?text=CampusPass'"><div class="event-card-body"><div class="d-flex justify-content-between gap-2"><span class="category-pill"><?=e($ev['category'])?></span><span class="status-pill status-<?=e($ev['status'])?>"><?=e($ev['status'])?></span></div><h2 class="h5 mt-3"><?=e($ev['title'])?></h2><div class="event-meta mb-3"><span><i class="bi bi-calendar3"></i><?=e(date('M j, Y',strtotime($ev['event_date'])))?></span><span><i class="bi bi-geo-alt"></i><?=e($ev['venue'])?></span></div><p class="muted"><?=e(mb_strimwidth($ev['description'],0,100,'…'))?></p><div class="d-flex justify-content-between small muted mb-3"><span><?=number_format($remaining)?> seats left</span><span>Capacity <?=number_format((int)$ev['capacity'])?></span></div><a class="btn btn-outline-primary w-100" href="event-details.php?id=<?=(int)$ev['id']?>">View details <i class="bi bi-arrow-right ms-1"></i></a></div></article></div><?php endforeach; ?></div></div></section><?php require __DIR__.'/includes/footer.php'; ?>
